(()=>{
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=s=>String(s??'').normalize('NFD').replace(/\p{M}/gu,'').toLowerCase().replace(/[^\p{L}\p{N}\s]/gu,' ').replace(/\s+/g,' ').trim();
const lesson=()=>window.BoraCourses[0].lessons.find(l=>l.id===location.hash.split('?')[0].split('/')[2]);
const course=()=>window.BoraCourses[0];
let cleanup=()=>{};function stop(){cleanup();cleanup=()=>{}}
function record(u,l){u.courseProgress??={};const r=u.courseProgress['pt/'+l.id]??={stage:0,answers:{},attempts:0,correct:0,note:'',done:false};r.guided??={version:1,index:0,answers:{},drafts:{},tokens:[],startedAt:new Date().toISOString()};return r}
function activities(l){const c=window.BoraLessonContent[l.id],bank=window.BoraLessonTests.bank(l.id),listening=l.examples[0],audio=Object.values(window.BoraAudioManifest||{}).find(a=>norm(a.text)===norm(listening[0]));return[
{type:'intro',title:'Разберём по шагам'},
{type:'words',title:'Нужные слова и фразы'},
{type:'examples',title:'Посмотри и послушай'},
{type:'listen',title:'Пойми на слух',audio,options:[listening[1],...l.examples.slice(1,3).map(e=>e[1])],answer:0,why:listening[0]+' — '+listening[1]},
{type:'build',title:'Собери фразу',tokens:l.examples[0][0].split(/\s+/),answer:l.examples[0][0],why:l.examples[0][1]},
{type:'short',title:'Заполни пропуск',q:bank[4].q,accepted:bank[4].answer,why:bank[4].why},
{type:'short',title:'Верни букву',q:'Вставь пропущенную букву: '+c.spell[0],accepted:[c.spell[1]],why:c.spell[2]},
...l.quiz.map(q=>({type:'choice',title:'Проверь, как это работает',q:q[0],options:q[1],answer:q[2],why:q[3]})),
{type:'read',title:'Прочитай короткую историю',text:c.read[0],q:c.read[1],options:c.read[2],answer:c.read[3],why:c.read[2][c.read[3]]},
{type:'photo',title:'Подпиши ситуацию',...c.photo},
{type:'short',title:'Напиши сам',q:l.write[0],accepted:l.write[1],why:l.write[2]},
{type:'write',title:'Твой маленький текст'},
...bank.map(q=>({type:'test',title:'Закрепление · '+(bank.indexOf(q)+1)+' из 5',q:q.q,options:q.type==='choice'?q.options:null,answer:q.answer,testId:q.id,why:q.why})),
{type:'finish',title:'Занятие завершено'}]}
function choices(a,selected){return `<div class="guided-options">${a.options.map((v,i)=>`<button class="option ${Number(selected)===i?(i===Number(a.answer)?'answer-correct':'answer-wrong'):selected!==undefined&&i===Number(a.answer)?'answer-reveal':''}" data-guided-choice="${i}" ${selected!==undefined&&(a.type==='test'||Number(selected)===Number(a.answer))?'disabled':''}>${esc(v)}</button>`).join('')}</div>`}
function page(u){const l=lesson();if(!l)return window.BoraLearning.page(u);const r=record(u,l),s=r.guided,list=activities(l),i=Math.max(0,Math.min(list.length-1,s.index)),a=list[i],v=s.answers[i],c=window.BoraLessonContent[l.id];let body='',next=!!v?.passed||['intro','words','examples'].includes(a.type)||a.type==='photo'&&!!s.drafts[i]?.trim();const example=(pt,ru)=>`<div class="guided-example"><strong lang="pt-BR">${esc(pt)}</strong><p>${esc(ru)}</p>${window.BoraAudio.button(pt)}</div>`;
if(a.type==='intro')body=`<p class="guided-goal">${esc(l.scene)}</p><section class="guided-idea"><h2>Самое главное</h2>${l.id==='oi'?'<p>Португальский пишется латинскими буквами. Сначала слушай и повторяй короткие фразы; правила чтения будем добавлять понемногу.</p>':''}<p>${esc(window.BoraComfort.simple[l.id])}</p></section><section><h2>Как устроена фраза</h2><p>${esc(c.rule)}</p></section>${window.BoraKit.ruleHTML(l.id)}${l.mistake?`<details><summary>Что легко перепутать</summary><p>${esc(l.mistake)}</p></details>`:''}<p class="small">Впереди слова, аудирование, фразы, чтение, картинка и небольшой текст. Можно продолжить позже с этого места.</p>`;
if(a.type==='words'){const words=window.BoraKit.vocabulary(l.id),wi=Math.min(s.wordIndex||0,words.length-1),w=words[wi];body=`<p>Сначала разберём слова. Нажми «Показать перевод», попробуй вспомнить и переходи дальше. Весь список доступен ниже.</p><section class="word-trainer"><p>Карточка ${wi+1} из ${words.length}</p><h2 lang="pt-BR">${esc(w.pt)}</h2>${window.BoraKit.audio(w.pt)}<details><summary>Показать перевод</summary><p>${esc(w.ru)}</p></details><div class="row"><button class="btn alt" id="lesson-word-prev" ${wi?'':'disabled'}>← Предыдущее</button><button class="btn" id="lesson-word-next">${wi===words.length-1?'Ещё раз':'Следующее слово →'}</button></div></section><details><summary>Все слова этого занятия</summary>${window.BoraKit.wordsHTML(l.id,u)}</details><a href="#dictionary/${l.id}">Открыть словарь и правило →</a>`}
if(a.type==='examples')body=`<p>Слушай по одной фразе. Повтори её вслух для себя — микрофон не нужен.</p>${l.examples.map(([pt,ru])=>example(pt,ru)).join('')}`;
if(a.type==='listen')body=`<p>Послушай фразу и выбери её смысл.</p>${a.audio?`<audio class="guided-listening" controls preload="metadata" src="${a.audio.src}" aria-label="Фраза для аудирования"></audio><p class="small">${a.audio.kind==='native'?'Запись носителя':'Синтетический голос · Бразилия'}</p>`:'<p>Аудио временно недоступно. Можно продолжить занятие и повторить аудирование позже.</p><button class="btn alt" id="guided-listen-skip">Продолжить без аудио</button>'}${choices(a,v?.answer)}`;
if(a.type==='choice'||a.type==='read'){body=(a.text?`<article class="guided-reading" lang="pt-BR">${esc(a.text)}</article><details><summary>Перевод истории</summary><p class="reading-translation">${esc(window.BoraKit.readingRU[l.id])}</p></details><details><summary>Слова из истории</summary><p>${window.BoraKit.vocabulary(l.id).map(w=>esc(w.pt)+' — '+esc(w.ru)).join('; ')}.</p></details>`:'')+`<h2>${esc(a.q)}</h2>${choices(a,v?.answer)}`}
if(a.type==='build'){const tokens=s.tokens||[],rotation=a.tokens.map((text,id)=>({text,id})),pool=rotation.slice(1).concat(rotation[0]);body=`<p>${esc(a.why)} Нажимай слова по порядку.</p><div class="sentence-tray" aria-label="Твоя фраза">${tokens.map(n=>`<span>${esc(a.tokens[n])}</span>`).join('')||'<span class="small">Здесь появится фраза</span>'}</div><div class="word-bank">${pool.map(t=>`<button class="btn alt" data-guided-token="${t.id}" ${tokens.includes(t.id)||v?.passed?'disabled':''}>${esc(t.text)}</button>`).join('')}</div><div class="row"><button class="btn alt" id="guided-undo">Убрать последнее слово</button><button class="btn" id="guided-check-build" ${v?.passed?'disabled':''}>Проверить фразу</button></div>`}
if(a.type==='short')body=`<h2>${esc(a.q)}</h2><form id="guided-short"><label>Твой ответ<input id="guided-input" maxlength="250" autocomplete="off" value="${esc(s.drafts[i]||'')}" ${v?.passed?'disabled':''} required></label><button class="btn" ${v?.passed?'disabled':''}>Проверить</button></form>`;
if(a.type==='photo'){const phrase=l.examples[0];body=`<img class="guided-photo topic-illustration" src="/assets/scenes/${l.id}.svg" alt="${esc(l.scene)}" width="720" height="360"><p>${esc(l.scene)} Подпиши ситуацию знакомой фразой. Описывать фон и придумывать новые слова не нужно.</p>${example(phrase[0],phrase[1])}<details><summary>Разобрать каждое слово</summary>${window.BoraKit.ruleHTML(l.id)}</details><label>Напиши реплику человека<textarea id="guided-photo-note" maxlength="600" placeholder="Можно повторить или изменить образец выше…">${esc(s.drafts[i]||'')}</textarea></label><p class="small">Это твоя самостоятельная проба. Она сохраняется без автоматической оценки.</p>`}
if(a.type==='write')body=`<p>${esc(c.write)}</p><details><summary>Посмотреть образец и перевод</summary>${example(c.model[0],c.model[1])}</details><form id="guided-writing"><label>Твой текст<textarea id="guided-text" maxlength="1800" required placeholder="Начни с одной фразы. Потом добавь ещё одну…">${esc(s.drafts[i]||'')}</textarea></label><fieldset class="writing-checklist"><legend>Проверь свой текст</legend>${c.checks.map((t,n)=>`<label><input type="checkbox" data-writing-check="${n}" ${s.writingChecks?.[n]?'checked':''}>${esc(t)}</label>`).join('')}</fieldset><button class="btn">Сохранить текст</button></form><p class="small">Свободный текст не получает автоматическую отметку «верно». Сравни смысл с образцом; разные правильные ответы возможны.</p>`;
if(a.type==='test'){next=v!==undefined;body=`<h2>${esc(a.q)}</h2>${a.options?choices(a,v?.answer):`<form id="guided-test-write"><label>Твой ответ<input id="guided-input" maxlength="250" value="${esc(s.drafts[i]||'')}" ${v?'disabled':''}></label><button class="btn" ${v?'disabled':''}>Ответить</button></form>`}<button class="btn alt" id="guided-test-unknown" ${v?'disabled':''}>Пока не знаю</button><p class="small">После ответа появится объяснение. Ошибки не мешают продолжить.</p>`}
if(a.type==='finish'){const nextLesson=course().lessons[course().lessons.indexOf(l)+1],grade=s.testResult;body=`<p>Ты дошёл до конца занятия. Можно продолжить обучение или вернуться к отложенным заданиям.</p>${Object.entries(s.skipped||{}).some(([,v])=>v)?`<section class="skipped-tasks"><h2>Отложенные задания</h2>${Object.entries(s.skipped).filter(([,v])=>v).map(([index])=>`<p><button class="btn alt" data-guided-resume="${index}">Шаг ${Number(index)+1}: ${esc(list[Number(index)]?.title)} →</button></p>`).join('')}</section>`:''}${grade?`<div class="guided-score"><strong>${grade.correct} из 5</strong><p>${grade.passed?'Основное получилось.':'Ошибки показывают, что стоит повторить. Можно двигаться дальше в своём темпе.'}</p></div>${grade.results.map(result=>{const q=window.BoraLessonTests.bank(l.id).find(q=>q.id===result.id);return `<details><summary>${result.correct?'✓':'↻'} ${esc(q.q)}</summary><p>${esc(q.why)}</p></details>`}).join('')}`:''}<div class="row">${nextLesson?`<a class="btn yellow" href="#courses/pt/${nextLesson.id}">Следующее занятие →</a>`:'<a class="btn yellow" href="#exam">Перейти к учебному пробнику →</a>'}<a class="btn alt" href="#courses/pt">Все занятия</a></div><p><button class="btn alt" id="guided-restart">Повторить занятие с начала</button></p>`}
const feedback=v&&a.type!=='finish'?`<div class="feedback ${a.type==='write'?'neutral':v.passed?'answer-correct':'bad answer-wrong'}" role="status">${a.type==='write'?'Текст и твоя самопроверка сохранены.':v.passed?'✓ Верно! '+esc(a.why||''):'✕ Попробуем ещё. '+esc(a.why||'Попробуй другой вариант.')}</div>`:'';
return `<div class="narrow guided-lesson"><div class="guided-top"><a class="back" href="#courses/pt">← Все занятия</a><span>Урок ${course().lessons.indexOf(l)+1} из 30</span></div><div class="panel"><p class="eyebrow">${esc(l.title)} · ${i+1} из ${list.length}</p><progress value="${i+1}" max="${list.length}" aria-label="Шаг занятия"></progress><h1>${a.title}</h1>${s.skipped?.[i]?'<p class="deferred-note">Это задание отложено. Сейчас можно его выполнить.</p>':''}${body}${feedback}${a.type!=='finish'?`<div class="guided-footer">${i?'<button class="btn alt" id="guided-back">← Назад</button>':''}<button class="btn" id="guided-next" ${next?'':'disabled'}>${i===list.length-2?'Завершить занятие':'Продолжить →'}</button></div>${!v?.passed&&!['intro','words','examples'].includes(a.type)?'<button class="skip-task" id="guided-skip">Пропустить и вернуться позже →</button>':''}<div class="guided-help"><details><summary>Непонятно — объяснить проще</summary><p>${esc(a.type==='photo'?'Посмотри на людей или предметы в ситуации. Напиши реплику из образца, перевод уже дан. Не нужно описывать всё изображение.':a.type==='build'?'Посмотри на перевод. Нажимай слова слева направо, чтобы получить знакомую фразу. Убрать последнее слово можно отдельной кнопкой.':a.type==='short'||a.type==='test'?a.why||c.rule:a.type==='read'?'Прочитай вопрос по-русски, затем ищи в истории имя, время или знакомое слово. Новые кусочки можно посмотреть в словаре.':c.rule)}</p><p><a href="#dictionary/${l.id}">Слова и правило этого занятия</a></p><p><a data-comfort-start="oi" href="#courses/pt/oi">Вернуться к первым фразам</a></p></details><p class="small">Хочешь остановиться? Нажми «Все занятия». Ответы сохраняются в аккаунте.</p></div>`:''}</div><div class="guided-audio-box"><audio id="guided-player" hidden controls preload="none" aria-label="Выбранная фраза"></audio><p id="guided-audio-status" role="status"></p></div></div>`}
function bind(u,saveState,render){const l=lesson(),$=s=>document.querySelector(s);if(!l||!$('#guided-next')&&!$('#guided-restart'))return;const save=()=>{u.currentLesson=l.id;saveState()};const r=record(u,l),s=r.guided,list=activities(l),i=s.index,a=list[i];let alive=true;cleanup=()=>{alive=false;document.querySelectorAll('.guided-lesson audio').forEach(p=>{p.pause();p.removeAttribute('src');p.load()})};const paint=()=>{save();render();window.scrollTo(0,0)};const on=(q,f)=>{const el=$(q);if(el)el.onclick=f};const store=(answer,passed)=>{if(passed&&s.skipped)delete s.skipped[i];s.answers[i]={answer,passed,at:new Date().toISOString()};if(a.type!=='test'&&a.type!=='write'){r.attempts=(r.attempts||0)+1;if(passed)r.correct=(r.correct||0)+1;window.BoraStudy?.track(u,course(),l,a.type,passed,answer)}paint()};
on('#guided-skip',()=>{s.skipped??={};s.skipped[i]=true;delete s.answers[i];s.index=Math.min(list.length-1,i+1);s.tokens=[];if(s.index===list.length-1){s.index=i;store('__unknown__',false);s.skipped[i]=true;$('#guided-next').onclick();return}paint()});document.querySelectorAll('[data-guided-resume]').forEach(b=>b.onclick=()=>{s.index=Number(b.dataset.guidedResume);s.tokens=[];paint()});on('#lesson-word-prev',()=>{s.wordIndex=Math.max(0,(s.wordIndex||0)-1);paint()});on('#lesson-word-next',()=>{s.wordIndex=((s.wordIndex||0)+1)%window.BoraKit.vocabulary(l.id).length;paint()});on('#guided-back',()=>{s.index=Math.max(0,i-1);s.tokens=[];paint()});on('#guided-next',()=>{if(!$('#guided-next').disabled){s.index=Math.min(list.length-1,i+1);s.tokens=[];if(s.index===list.length-1){const tests=list.map((q,index)=>({q,index})).filter(v=>v.q.type==='test'),answers=Object.fromEntries(tests.map(v=>[v.q.testId,s.answers[v.index]?.answer??'__unknown__'])),grade=window.BoraLessonTests.grade(l.id,answers);s.testResult=grade;s.finishedAt=new Date().toISOString();r.done=true;r.finishedAt=r.finishedAt||s.finishedAt;r.reviewAt=new Date(Date.now()+86400000).toISOString();u.assessment??={};u.assessment.lessonTests??={};const rec=u.assessment.lessonTests[l.id]??={history:[]};if(rec.last)rec.history=[...(rec.history||[]),rec.last].slice(-3);rec.last={...grade,id:'guided-'+l.id+'-'+Date.now(),at:Date.now()};window.BoraComfort?.advance(u,l.id)}paint()}});
on('#guided-restart',()=>{r.guidedHistory=[...(r.guidedHistory||[]),{finishedAt:s.finishedAt,testResult:s.testResult,drafts:s.drafts}].slice(-2);s.index=0;s.answers={};s.drafts={};s.tokens=[];s.writingChecks=[];s.skipped={};s.wordIndex=0;delete s.finishedAt;delete s.testResult;paint()});on('#guided-listen-skip',()=>store('audio-unavailable',true));
document.querySelectorAll('[data-guided-choice]').forEach(b=>b.onclick=()=>{const answer=Number(b.dataset.guidedChoice);if(a.type==='test'){store(String(answer),answer===a.answer);return}store(answer,answer===a.answer)});
document.querySelectorAll('[data-guided-token]').forEach(b=>b.onclick=()=>{const n=Number(b.dataset.guidedToken);if(!s.tokens.includes(n)){s.tokens.push(n);paint()}});on('#guided-undo',()=>{s.tokens.pop();delete s.answers[i];paint()});on('#guided-check-build',()=>store(s.tokens.map(n=>a.tokens[n]).join(' '),norm(s.tokens.map(n=>a.tokens[n]).join(' '))===norm(a.answer)));
const input=$('#guided-input');if(input)input.oninput=()=>{s.drafts[i]=input.value;save()};if($('#guided-short'))$('#guided-short').onsubmit=e=>{e.preventDefault();store(input.value,a.accepted.some(v=>norm(v)===norm(input.value)))};if($('#guided-test-write'))$('#guided-test-write').onsubmit=e=>{e.preventDefault();store(input.value,a.answer.some(v=>norm(v)===norm(input.value)))};on('#guided-test-unknown',()=>store('__unknown__',false));
const photo=$('#guided-photo-note');if(photo)photo.oninput=()=>{s.drafts[i]=photo.value;if(photo.value.trim()&&s.skipped)delete s.skipped[i];$('#guided-next').disabled=!photo.value.trim();save()};const text=$('#guided-text');if(text){text.oninput=()=>{s.drafts[i]=text.value;delete s.answers[i];$('#guided-next').disabled=true;save()};document.querySelectorAll('[data-writing-check]').forEach(b=>b.onchange=()=>{s.writingChecks??=[];s.writingChecks[Number(b.dataset.writingCheck)]=b.checked;delete s.answers[i];$('#guided-next').disabled=true;save()});$('#guided-writing').onsubmit=e=>{e.preventDefault();if(!text.value.trim()||![0,1,2].every(n=>s.writingChecks?.[n])){let p=$('#guided-writing-status');if(!p){p=document.createElement('p');p.id='guided-writing-status';p.setAttribute('role','status');$('#guided-writing').append(p)}p.textContent='Напиши текст и отметь три пункта самопроверки.';return}store('text-saved',true)}}
document.querySelectorAll('.guided-lesson [data-audio-id]').forEach(b=>b.onclick=async()=>{window.BoraKit.cancelSpeech();const p=$('#guided-player'),status=$('#guided-audio-status'),audio=Object.values(window.BoraAudioManifest).find(a=>a.id===b.dataset.audioId);if(!audio)return;p.hidden=false;p.src=audio.src;status.textContent=audio.kind==='native'?'Запись носителя':'Синтетический голос · Бразилия';try{await p.play()}catch{if(alive)status.textContent='Нажми ▶ в плеере или попробуй воспроизведение ещё раз.'}})
}
window.BoraLessons={page,bind,stop,activities,record,norm};
})();
